'use client'

import { useState, useEffect } from 'react'
import { createClientComponentClient } from '@/lib/supabase-client'
import { 
    Upload, Search, Copy, Check, 
    Image as ImageIcon, 
    ExternalLink, Calendar 
} from 'lucide-react'
import { motion, AnimatePresence } from 'framer-motion'

export function MediaExplorer() {
    const [view, setView] = useState<'library' | 'trips'>('library')
    const [loading, setLoading] = useState(true)
    const [uploading, setUploading] = useState(false)
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const [files, setFiles] = useState<any[]>([])
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const [tripsWithMedia, setTripsWithMedia] = useState<any[]>([])
    const [search, setSearch] = useState('')
    const [copiedUrl, setCopiedUrl] = useState<string | null>(null)
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const [supabase, setSupabase] = useState<any>(null)

    useEffect(() => {
        const client = createClientComponentClient()
        setSupabase(client)
        if (view === 'library') {
            fetchLibraryFiles(client)
        } else {
            fetchTripMedia(client)
        }
    }, [view])

  // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const fetchLibraryFiles = async (client: any) => {
        setLoading(true)
        try {
  // eslint-disable-next-line unused-imports/no-unused-vars
            const { data, error } = await client.storage
                .from('images')
                .list('trips', {
                    limit: 100,
                    offset: 0,
                    sortBy: { column: 'created_at', order: 'desc' },
                })

            if (data) {
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
                const filesWithUrls = data.map((f: any) => ({
                    ...f,
                    url: client.storage.from('images').getPublicUrl(`trips/${f.name}`).data.publicUrl
                }))
                setFiles(filesWithUrls)
            }
        } catch (err) {
            console.error('Error fetching library:', err)
        } finally {
            setLoading(false)
        }
    }

  // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const fetchTripMedia = async (client: any) => {
        setLoading(true)
        try {
  // eslint-disable-next-line unused-imports/no-unused-vars
            const { data, error } = await client
                .from('trips')
                .select('id, name, image_url, itinerary')
                .order('created_at', { ascending: false })

            if (data) {
                setTripsWithMedia(data)
            }
        } catch (err) {
            console.error('Error fetching trip media:', err)
        } finally {
            setLoading(false)
        }
    }

    const handleUpload = async (file: File) => {
        if (!supabase || !file) return
        setUploading(true)
        try {
            const fileExt = file.name.split('.').pop()
            const fileName = `${Date.now()}-${Math.random().toString(36).substring(7)}.${fileExt}`
            const filePath = `trips/${fileName}`

            const { error: uploadError } = await supabase.storage
                .from('images')
                .upload(filePath, file)

            if (uploadError) throw uploadError

            // Refresh library if on library view
            if (view === 'library') fetchLibraryFiles(supabase)
            alert('Upload successful!')
        } catch (error: unknown) {
            console.error('Upload error:', error)
            alert(`Upload failed: ${error.message}`)
        } finally {
            setUploading(false)
        }
    }

    const copyToClipboard = (url: string) => {
        navigator.clipboard.writeText(url)
        setCopiedUrl(url)
        setTimeout(() => setCopiedUrl(null), 2000)
    }

    const filteredFiles = files.filter(f => f.name.toLowerCase().includes(search.toLowerCase()))

    return (
        <div className="space-y-6">
            {/* Toolbar */}
            <div className="flex flex-col md:flex-row gap-4 justify-between items-start md:items-center">
                <div className="flex gap-2 p-1 bg-background/50 border border-muted-foreground/10 rounded-xl overflow-hidden">
                    <button 
                        onClick={() => setView('library')}
                        className={`px-4 py-1.5 rounded-lg text-xs font-bold uppercase tracking-widest transition-all ${view === 'library' ? 'bg-primary text-background' : 'text-muted-foreground hover:text-foreground'}`}
                    >
                        <ImageIcon className="h-3.5 w-3.5 inline mr-2" />
                        Library
                    </button>
                    <button 
                        onClick={() => setView('trips')}
                        className={`px-4 py-1.5 rounded-lg text-xs font-bold uppercase tracking-widest transition-all ${view === 'trips' ? 'bg-primary text-background' : 'text-muted-foreground hover:text-foreground'}`}
                    >
                        <Calendar className="h-3.5 w-3.5 inline mr-2" />
                        Trip Media
                    </button>
                </div>

                <div className="flex gap-3 w-full md:w-auto">
                    <div className="relative flex-1 md:w-64">
                        <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-3.5 w-3.5 text-muted-foreground" />
                        <input 
                            type="text" 
                            value={search}
                            onChange={(e) => setSearch(e.target.value)}
                            placeholder="Search assets..."
                            className="w-full pl-9 pr-4 py-2 bg-background border border-muted-foreground/20 rounded-xl text-xs focus:border-primary outline-none"
                        />
                    </div>
                    <label className="flex items-center gap-2 px-4 py-2 bg-primary/10 text-primary rounded-xl cursor-pointer hover:bg-primary/20 transition-all text-xs font-bold uppercase tracking-widest shrink-0">
                        <Upload className="h-3.5 w-3.5" />
                        {uploading ? 'Processing...' : 'Upload'}
                        <input type="file" accept="image/*" className="hidden" onChange={(e) => {
                            const file = e.target.files?.[0]
                            if (file) handleUpload(file)
                        }} />
                    </label>
                </div>
            </div>

            {/* Content Container */}
            <div className="min-h-[400px]">
                <AnimatePresence mode="wait">
                    {loading ? (
                        <motion.div 
                            key="loading"
                            initial={{ opacity: 0 }}
                            animate={{ opacity: 1 }}
                            exit={{ opacity: 0 }}
                            className="flex flex-col items-center justify-center py-32 text-muted-foreground"
                        >
                            <div className="h-8 w-8 border-2 border-primary/20 border-t-primary rounded-full animate-spin mb-4" />
                            <p className="text-xs uppercase tracking-[0.4em]">Querying Storage...</p>
                        </motion.div>
                    ) : view === 'library' ? (
                        <motion.div 
                            key="library"
                            initial={{ opacity: 0, y: 10 }}
                            animate={{ opacity: 1, y: 0 }}
                            exit={{ opacity: 0, y: -10 }}
                            className="grid grid-cols-2 md:grid-cols-4 lg:grid-cols-5 gap-4"
                        >
                            {filteredFiles.map((file) => (
                                <MediaCard 
                                    key={file.name} 
                                    url={file.url} 
                                    name={file.name} 
                                    onCopy={() => copyToClipboard(file.url)}
                                    isCopied={copiedUrl === file.url}
                                />
                            ))}
                            {filteredFiles.length === 0 && (
                                <div className="col-span-full py-32 text-center text-muted-foreground font-serif italic">
                                    No assets found in target directory.
                                </div>
                            )}
                        </motion.div>
                    ) : (
                        <motion.div 
                            key="trips"
                            initial={{ opacity: 0, y: 10 }}
                            animate={{ opacity: 1, y: 0 }}
                            exit={{ opacity: 0, y: -10 }}
                            className="space-y-12"
                        >
                            {tripsWithMedia.map((trip) => (
                                <div key={trip.id} className="space-y-6 bg-card border border-muted-foreground/10 p-6 rounded-2xl overflow-hidden relative">
                                    <div className="noise-overlay opacity-[0.03]" />
                                    <div className="flex items-center gap-4 relative z-10">
  // eslint-disable-next-line react/jsx-no-comment-textnodes
                                        <div className="w-12 h-12 rounded-lg overflow-hidden border border-muted-foreground/10 shrink-0">
  // eslint-disable-next-line @next/next/no-img-element
  // eslint-disable-next-line @next/next/no-img-element
  // eslint-disable-next-line @next/next/no-img-element
                                            <img src={trip.image_url || '/placeholder.jpg'} alt="" className="w-full h-full object-cover" />
                                        </div>
                                        <div>
                                            <h3 className="font-serif text-lg text-foreground">{trip.name}</h3>
                                            <p className="text-[10px] uppercase tracking-widest text-muted-foreground">Expedition Media Assets</p>
                                        </div>
                                    </div>

                                    <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6 relative z-10">
                                        {/* Main Hero Asset */}
                                        <div className="space-y-3">
                                            <span className="text-[9px] uppercase tracking-[0.3em] text-primary/60 font-bold">Hero Asset</span>
                                            <MediaCard 
                                                url={trip.image_url} 
                                                name="Hero Image" 
                                                onCopy={() => trip.image_url && copyToClipboard(trip.image_url)}
                                                isCopied={copiedUrl === trip.image_url}
                                            />
                                        </div>

  // eslint-disable-next-line react/jsx-no-comment-textnodes
                                        {/* Itinerary Assets */}
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
                                        {trip.itinerary?.map((day: any, i: number) => (
                                            day.image_url && (
                                                <div key={i} className="space-y-3">
                                                    <span className="text-[9px] uppercase tracking-[0.3em] text-muted-foreground/60 font-bold">Day {day.day || i + 1}</span>
                                                    <MediaCard 
                                                        url={day.image_url} 
                                                        name={day.title || `Day ${day.day}`} 
                                                        onCopy={() => copyToClipboard(day.image_url)}
                                                        isCopied={copiedUrl === day.image_url}
                                                    />
                                                </div>
                                            )
                                        ))}
                                    </div>
                                </div>
                            ))}
                        </motion.div>
                    )}
                </AnimatePresence>
            </div>
        </div>
    )
}

function MediaCard({ url, name, onCopy, isCopied }: { url: string; name: string; onCopy: () => void; isCopied: boolean }) {
    if (!url) return (
        <div className="aspect-square rounded-xl bg-muted-foreground/5 border border-dashed border-muted-foreground/10 flex items-center justify-center">
            <p className="text-[10px] text-muted-foreground uppercase tracking-widest">No Image</p>
        </div>
    )

    return (
  // eslint-disable-next-line react/jsx-no-comment-textnodes
        <div className="group relative aspect-square rounded-xl overflow-hidden border border-muted-foreground/10 bg-muted-foreground/5 hover:border-primary/30 transition-all">
  // eslint-disable-next-line @next/next/no-img-element
  // eslint-disable-next-line @next/next/no-img-element
  // eslint-disable-next-line @next/next/no-img-element
            <img src={url} alt={name} className="w-full h-full object-cover transition-transform duration-700 group-hover:scale-110" />
            <div className="absolute inset-0 bg-gradient-to-t from-black/80 via-black/20 to-transparent opacity-0 group-hover:opacity-100 transition-opacity" />

            <div className="absolute top-2 right-2 flex gap-1 opacity-0 group-hover:opacity-100 transition-opacity translate-y-2 group-hover:translate-y-0 duration-300">
                <button 
                    onClick={onCopy}
                    className="p-1.5 bg-background/80 backdrop-blur-md rounded-lg text-foreground hover:bg-primary hover:text-background transition-all"
                    title="Copy URL"
                >
                    {isCopied ? <Check className="h-3.5 w-3.5" /> : <Copy className="h-3.5 w-3.5" />}
                </button>
                <a 
                    href={url} 
                    target="_blank" 
                    rel="noreferrer"
                    className="p-1.5 bg-background/80 backdrop-blur-md rounded-lg text-foreground hover:bg-foreground hover:text-background transition-all"
                >
                    <ExternalLink className="h-3.5 w-3.5" />
                </a>
            </div>

            <div className="absolute bottom-2 left-2 right-2 opacity-0 group-hover:opacity-100 transition-opacity translate-y-2 group-hover:translate-y-0 duration-300 pointer-events-none">
                <p className="text-[9px] text-white/60 truncate font-mono bg-black/40 px-2 py-1 rounded backdrop-blur-sm">
                    {name}
                </p>
            </div>
        </div>
    )
}

'use client'

import { useState, useEffect } from 'react'
import { createClientComponentClient } from '@/lib/supabase-client'
import { Plus, X, Upload, Image as ImageIcon } from 'lucide-react'

interface StayFormProps {
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  stay?: any
  onSuccess: () => void
}

export function StayForm({ stay, onSuccess }: StayFormProps) {
  const [loading, setLoading] = useState(false)
  const [uploading, setUploading] = useState(false)
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  const [supabase, setSupabase] = useState<any>(null)

  const [formData, setFormData] = useState({
    name: stay?.name || '',
    location: stay?.location || '',
    tagline: stay?.tagline || '',
    description: stay?.description || '',
    price: stay?.price || 0,
    room_type: stay?.room_type || 'Dorm',
    image_url: stay?.image_url || '',
    amenities: stay?.amenities || [''],
    gallery: stay?.gallery || [''],
    capacity: stay?.capacity || 4,
    status: stay?.status || 'draft',
  })

  useEffect(() => {
    setSupabase(createClientComponentClient())
  }, [])

  // Re-sync form when a different stay is passed (e.g. switching edits in drawer)
  useEffect(() => {
    setFormData({
      name: stay?.name || '',
      location: stay?.location || '',
      tagline: stay?.tagline || '',
      description: stay?.description || '',
      price: stay?.price || 0,
      room_type: stay?.room_type || 'Dorm',
      image_url: stay?.image_url || '',
      amenities: stay?.amenities || [''],
      gallery: stay?.gallery || [''],
      capacity: stay?.capacity || 4,
      status: stay?.status || 'draft',
  // eslint-disable-next-line react-hooks/exhaustive-deps
  // eslint-disable-next-line react-hooks/exhaustive-deps
    })
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [stay?.id])

  const handleImageUpload = async (file: File, callback: (url: string) => void) => {
    if (!supabase || !file) return
    setUploading(true)
    try {
      const fileExt = file.name.split('.').pop()
      const fileName = `${Date.now()}-${Math.random().toString(36).substring(7)}.${fileExt}`
      const filePath = `stays/${fileName}`

      const { error: uploadError } = await supabase.storage
        .from('images')
        .upload(filePath, file)

      if (uploadError) throw uploadError

      const { data: { publicUrl } } = supabase.storage
        .from('images')
        .getPublicUrl(filePath)

      callback(publicUrl)
    } catch (error: unknown) {
      console.error('Upload error:', error)
      alert(`Upload failed: ${error.message}`)
    } finally {
      setUploading(false)
    }
  }

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault()
    if (!supabase) return
    setLoading(true)

    try {
      const payload = {
        ...formData,
        amenities: formData.amenities.filter((a: string) => a.trim()),
        gallery: formData.gallery.filter((g: string) => g.trim()),
      }

      if (stay?.id) {
        const response = await fetch('/api/admin/stays', {
          method: 'PATCH',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ id: stay.id, ...payload }),
        })
        const result = await response.json()
        if (!response.ok) throw new Error(result.error || 'Failed to update stay')
      } else {
        const response = await fetch('/api/admin/stays', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify(payload),
        })
        const result = await response.json()
        if (!response.ok) throw new Error(result.error || 'Failed to create stay')
      }
      onSuccess()
    } catch (error: unknown) {
      console.error('Save error:', error)
      alert(`Error saving stay: ${error.message}`)
    } finally {
      setLoading(false)
    }
  }

  const inputClass = "w-full px-4 py-2.5 bg-background border border-muted-foreground/20 rounded-xl text-foreground text-sm focus:border-primary focus:ring-1 focus:ring-primary outline-none transition-all"
  const labelClass = "block text-xs font-semibold text-foreground/80 uppercase tracking-wider mb-1.5"

  return (
    <form onSubmit={handleSubmit} className="p-6 bg-card border border-primary/10 rounded-2xl space-y-6 shadow-xl">
      <h3 className="font-serif text-xl text-foreground">{stay ? 'Edit Stay' : 'Add New Stay'}</h3>

      <div className="grid md:grid-cols-2 gap-5">
        <div>
          <label className={labelClass}>Stay Name *</label>
          <input type="text" value={formData.name} onChange={(e) => setFormData({ ...formData, name: e.target.value })} className={inputClass} required placeholder="e.g. Hillside Retreat" />
        </div>
        <div>
          <label className={labelClass}>Location</label>
          <input type="text" value={formData.location} onChange={(e) => setFormData({ ...formData, location: e.target.value })} className={inputClass} placeholder="e.g. Manali, HP" />
        </div>
      </div>

      <div>
        <label className={labelClass}>Tagline</label>
        <input type="text" value={formData.tagline} onChange={(e) => setFormData({ ...formData, tagline: e.target.value })} className={inputClass} placeholder="e.g. Where the mountains meet your soul" />
      </div>

      <div>
        <label className={labelClass}>Description</label>
        <textarea value={formData.description} onChange={(e) => setFormData({ ...formData, description: e.target.value })} className={`${inputClass} h-28 resize-y`} placeholder="Describe the stay experience..." />
      </div>

      <div className="grid md:grid-cols-3 gap-5">
        <div>
          <label className={labelClass}>Price (₹/night)</label>
          <input type="number" value={formData.price} onChange={(e) => setFormData({ ...formData, price: parseInt(e.target.value) || 0 })} className={inputClass} />
        </div>
        <div>
          <label className={labelClass}>Room Type</label>
          <select value={formData.room_type} onChange={(e) => setFormData({ ...formData, room_type: e.target.value })} className={inputClass}>
            <option value="Dorm">Dorm</option>
            <option value="Private Room">Private Room</option>
            <option value="Cottage">Cottage</option>
            <option value="Tent">Tent</option>
            <option value="Villa">Villa</option>
            <option value="Treehouse">Treehouse</option>
          </select>
        </div>
        <div>
          <label className={labelClass}>Capacity</label>
          <input type="number" value={formData.capacity} onChange={(e) => setFormData({ ...formData, capacity: parseInt(e.target.value) || 0 })} className={inputClass} />
        </div>
      </div>

      {/* Hero Image */}
      <div>
        <label className={labelClass}>Main Image</label>
        <div className="flex gap-3">
          <input type="url" value={formData.image_url} onChange={(e) => setFormData({ ...formData, image_url: e.target.value })} className={`${inputClass} flex-1`} placeholder="Paste URL or upload" />
          <label className="flex items-center gap-2 px-4 py-2 bg-primary/10 text-primary rounded-xl cursor-pointer hover:bg-primary/20 transition-all text-sm font-medium">
            <Upload className="h-4 w-4" />
            {uploading ? '...' : 'Upload'}
            <input type="file" accept="image/*" className="hidden" onChange={(e) => {
              const file = e.target.files?.[0]
              if (file) handleImageUpload(file, (url) => setFormData({ ...formData, image_url: url }))
            }} />
          </label>
        </div>
        {formData.image_url && (
  // eslint-disable-next-line react/jsx-no-comment-textnodes
          <div className="mt-3 relative w-48 h-32 rounded-xl overflow-hidden border border-muted-foreground/20">
  // eslint-disable-next-line @next/next/no-img-element
  // eslint-disable-next-line @next/next/no-img-element
  // eslint-disable-next-line @next/next/no-img-element
            <img src={formData.image_url} alt="Preview" className="w-full h-full object-cover" />
          </div>
        )}
      </div>

      {/* Gallery */}
      <div>
        <label className={labelClass}>Gallery Images</label>
        <p className="text-xs text-muted-foreground mb-2">Add additional photos for the stay gallery.</p>
        {formData.gallery.map((url: string, index: number) => (
          <div key={index} className="flex gap-2 mb-2">
            <input type="url" value={url} onChange={(e) => { const g = [...formData.gallery]; g[index] = e.target.value; setFormData({ ...formData, gallery: g }) }} className={`${inputClass} flex-1`} placeholder="Image URL" />
            <label className="flex items-center gap-1 px-3 py-2 bg-primary/10 text-primary rounded-lg cursor-pointer hover:bg-primary/20 transition-all text-xs">
              <ImageIcon className="h-3 w-3" />
              <input type="file" accept="image/*" className="hidden" onChange={(e) => {
                const file = e.target.files?.[0]
                if (file) handleImageUpload(file, (url) => { const g = [...formData.gallery]; g[index] = url; setFormData({ ...formData, gallery: g }) })
              }} />
  // eslint-disable-next-line react/jsx-no-comment-textnodes
            </label>
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
            {formData.gallery.length > 1 && <button type="button" onClick={() => setFormData({ ...formData, gallery: formData.gallery.filter((_: any, i: number) => i !== index) })} className="p-2 text-red-400 hover:bg-red-400/10 rounded-lg"><X className="h-4 w-4" /></button>}
          </div>
        ))}
        <button type="button" onClick={() => setFormData({ ...formData, gallery: [...formData.gallery, ''] })} className="flex items-center gap-2 px-4 py-2 border border-dashed border-primary/30 rounded-xl text-primary text-sm hover:bg-primary/5 transition-all w-full justify-center mt-2">
          <Plus className="h-4 w-4" /> Add Gallery Image
        </button>
      </div>

      {/* Amenities */}
      <div>
        <label className={labelClass}>Amenities</label>
        {formData.amenities.map((amenity: string, index: number) => (
          <div key={index} className="flex gap-2 mb-2">
  // eslint-disable-next-line react/jsx-no-comment-textnodes
            <input type="text" value={amenity} onChange={(e) => { const a = [...formData.amenities]; a[index] = e.target.value; setFormData({ ...formData, amenities: a }) }} className={`${inputClass} flex-1`} placeholder="e.g. Wi-Fi, Bonfire, Kitchen" />
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
            {formData.amenities.length > 1 && <button type="button" onClick={() => setFormData({ ...formData, amenities: formData.amenities.filter((_: any, i: number) => i !== index) })} className="p-2 text-red-400 hover:bg-red-400/10 rounded-lg"><X className="h-4 w-4" /></button>}
          </div>
        ))}
        <button type="button" onClick={() => setFormData({ ...formData, amenities: [...formData.amenities, ''] })} className="flex items-center gap-2 px-4 py-2 border border-dashed border-primary/30 rounded-xl text-primary text-sm hover:bg-primary/5 transition-all w-full justify-center mt-2">
          <Plus className="h-4 w-4" /> Add Amenity
        </button>
      </div>

      {/* Status */}
      <div>
        <label className={labelClass}>Status</label>
        <select value={formData.status} onChange={(e) => setFormData({ ...formData, status: e.target.value })} className={inputClass}>
          <option value="draft">Draft</option>
          <option value="published">Published</option>
          <option value="archived">Archived</option>
        </select>
      </div>

      {/* Submit */}
      <button type="submit" disabled={loading} className="w-full py-4 bg-primary text-background rounded-xl hover:bg-primary/90 transition-all font-sans font-bold shadow-lg shadow-primary/20 disabled:opacity-50 active:scale-[0.98]">
        {loading ? 'Saving...' : stay ? 'Update Stay' : 'Create Stay'}
      </button>
    </form>
  )
}

'use client'

import { useState, useEffect } from 'react'
import { Plus, Edit2, Trash2, MapPin, Bed, Users, X, Eye, RefreshCcw } from 'lucide-react'
import { StayForm } from './stay-form'
import { motion, AnimatePresence } from 'framer-motion'

export function StaysManager() {
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  const [stays, setStays] = useState<any[]>([])
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState<string | null>(null)
  const [drawerOpen, setDrawerOpen] = useState(false)
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  const [editingStay, setEditingStay] = useState<any>(null)
  const [togglingId, setTogglingId] = useState<string | null>(null)

  useEffect(() => {
    fetchStays()
  }, [])

  const fetchStays = async () => {
    setLoading(true)
    setError(null)
    try {
      const response = await fetch('/api/admin/stays', { cache: 'no-store' })
      const result = await response.json()

      if (!response.ok) {
        throw new Error(result.error || 'Failed to load stays')
      }

      setStays(result.data || [])
    } catch (err: unknown) {
      console.error('Stays fetch error:', err)
      setStays([])
      setError((err as Error)?.message || 'Failed to load stays')
    } finally {
      setLoading(false)
    }
  }

  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  const openEditor = (stay: any = null) => {
    setEditingStay(stay)
    setDrawerOpen(true)
  }

  const closeDrawer = () => {
    setDrawerOpen(false)
    setTimeout(() => setEditingStay(null), 300)
  }

  const handleDelete = async (id: string) => {
    if (confirm('Delete this stay? This action cannot be undone.')) {
      try {
        const response = await fetch(`/api/admin/stays?id=${id}`, { method: 'DELETE' })
        const result = await response.json()

        if (!response.ok) {
          throw new Error(result.error || 'Failed to delete stay')
        }

        fetchStays()
      } catch (err: unknown) {
        setError((err as Error)?.message || 'Failed to delete stay')
      }
    }
  }

  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  const toggleStatus = async (stay: any) => {
    const newStatus = stay.status === 'published' ? 'draft' : 'published'
    setTogglingId(stay.id)
    try {
      const response = await fetch('/api/admin/stays', {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ id: stay.id, status: newStatus }),
      })
      const result = await response.json()

      if (!response.ok) {
        throw new Error(result.error || 'Failed to update stay status')
      }

      setStays(prev => prev.map(s => s.id === stay.id ? { ...s, status: newStatus } : s))
    } catch (err: unknown) {
      setError((err as Error)?.message || 'Failed to update stay status')
    } finally {
      setTogglingId(null)
    }
  }

  return (
    <div className="relative">
      {/* ── Slide-Over Drawer ──────────────────────── */}
      <AnimatePresence>
        {drawerOpen && (
          <>
            <motion.div
              initial={{ opacity: 0 }}
              animate={{ opacity: 1 }}
              exit={{ opacity: 0 }}
              onClick={closeDrawer}
              className="fixed inset-0 bg-black/60 backdrop-blur-sm z-40"
            />
            <motion.div
              initial={{ x: '100%' }}
              animate={{ x: 0 }}
              exit={{ x: '100%' }}
              transition={{ type: 'spring', damping: 28, stiffness: 250 }}
              className="fixed right-0 top-0 h-full w-full max-w-2xl bg-background border-l border-white/5 z-50 flex flex-col overflow-hidden shadow-2xl"
            >
              <div className="flex items-center justify-between px-6 py-5 border-b border-white/5 shrink-0">
                <div>
                  <p className="text-[9px] uppercase tracking-[0.5em] text-muted-foreground/40 font-bold mb-1">
                    {editingStay ? 'Editing Stay' : 'New Stay'}
                  </p>
                  <h3 className="font-serif text-xl text-foreground">
                    {editingStay?.name || 'New Property'}
                  </h3>
                </div>
                <button onClick={closeDrawer} className="p-2 rounded-xl hover:bg-white/5 text-muted-foreground hover:text-foreground transition-all">
                  <X className="h-5 w-5" />
                </button>
              </div>
              <div className="flex-1 overflow-y-auto p-6">
                <StayForm
                  stay={editingStay}
                  onSuccess={() => {
                    closeDrawer()
                    fetchStays()
                  }}
                />
              </div>
            </motion.div>
          </>
        )}
      </AnimatePresence>

      {/* ── Main Content ───────────────────────────── */}
      <div className="space-y-8">
        {error && (
          <div className="rounded-xl border border-red-500/20 bg-red-500/10 px-4 py-3 text-sm text-red-300">
            {error}
          </div>
        )}
        <div className="flex flex-col sm:flex-row items-start sm:items-center justify-between gap-4">
          <div>
            <h2 className="font-serif text-2xl text-foreground">Stays & Retreats</h2>
            <p className="text-[10px] uppercase tracking-[0.4em] text-muted-foreground/40 font-bold mt-1">
              {stays.length} total · {stays.filter(s => s.status === 'published').length} live
            </p>
          </div>
          <div className="flex items-center gap-3">
            <button
              onClick={() => fetchStays()}
              className="p-2.5 rounded-xl border border-white/5 hover:bg-white/5 text-muted-foreground hover:text-foreground transition-all"
            >
              <RefreshCcw className="h-4 w-4" />
            </button>
            <button
              onClick={() => openEditor(null)}
              className="flex items-center gap-2 px-6 py-2.5 rounded-xl bg-primary text-background hover:bg-primary/90 transition-all font-sans font-semibold text-sm shadow-lg shadow-primary/20"
            >
              <Plus className="h-4 w-4" />
              Add New Stay
            </button>
          </div>
        </div>

        <div className="grid gap-3">
          {loading ? (
            <div className="py-20 text-center text-muted-foreground animate-pulse font-sans">Loading stays...</div>
          ) : stays.length === 0 ? (
            <div className="py-20 text-center border-2 border-dashed border-muted-foreground/10 rounded-2xl">
              <p className="font-sans text-muted-foreground italic mb-4">No stays yet.</p>
              <button
                onClick={() => openEditor(null)}
                className="px-6 py-2.5 bg-primary/10 text-primary border border-primary/20 rounded-xl text-sm font-semibold hover:bg-primary/20 transition-all"
              >
                <Plus className="h-4 w-4 inline mr-2" />Create your first property
              </button>
            </div>
          ) : (
            stays.map((stay) => (
              <div key={stay.id} className="group p-4 sm:p-5 bg-card border border-white/5 rounded-2xl hover:border-primary/20 hover:shadow-xl transition-all duration-300">
                <div className="flex flex-col sm:flex-row gap-4 items-start">
                  {stay.image_url && (
  // eslint-disable-next-line react/jsx-no-comment-textnodes
                    <div className="w-full sm:w-20 h-36 sm:h-20 rounded-xl overflow-hidden shrink-0 border border-white/5">
  // eslint-disable-next-line @next/next/no-img-element
  // eslint-disable-next-line @next/next/no-img-element
  // eslint-disable-next-line @next/next/no-img-element
                      <img src={stay.image_url} alt={stay.name} className="w-full h-full object-cover transition-transform duration-700 group-hover:scale-110" />
                    </div>
                  )}
                  <div className="flex-1 min-w-0 space-y-2">
                    <div className="flex items-start justify-between gap-3">
                      <h3 className="font-serif text-lg text-foreground group-hover:text-primary transition-colors">{stay.name}</h3>
                      <button
                        onClick={() => toggleStatus(stay)}
                        disabled={togglingId === stay.id}
                        className={`flex items-center gap-1.5 px-3 py-1 rounded-full border text-[10px] font-bold uppercase tracking-wider transition-all shrink-0 ${stay.status === 'published'
                            ? 'bg-green-500/10 text-green-400 border-green-500/20 hover:bg-red-500/10 hover:text-red-400 hover:border-red-500/20'
                            : 'bg-yellow-500/10 text-yellow-400 border-yellow-500/20 hover:bg-green-500/10 hover:text-green-400 hover:border-green-500/20'
                          } disabled:opacity-50`}
                      >
                        {togglingId === stay.id ? '…' : stay.status === 'published' ? '● Live' : '○ Draft'}
                      </button>
                    </div>
                    <div className="flex flex-wrap gap-2 text-xs text-muted-foreground">
                      {stay.location && <span className="flex items-center gap-1 bg-white/[0.03] px-2 py-0.5 rounded"><MapPin className="h-3 w-3" />{stay.location}</span>}
                      <span className="flex items-center gap-1 bg-white/[0.03] px-2 py-0.5 rounded"><Bed className="h-3 w-3" />{stay.room_type || 'Room'}</span>
                      {stay.capacity && <span className="flex items-center gap-1 bg-white/[0.03] px-2 py-0.5 rounded"><Users className="h-3 w-3" />{stay.capacity} guests</span>}
                      <span className="font-bold text-primary bg-primary/10 px-2 py-0.5 rounded">₹{stay.price?.toLocaleString('en-IN')}/night</span>
                    </div>
                    {stay.tagline && <p className="text-xs text-muted-foreground italic truncate">{stay.tagline}</p>}
                  </div>
                </div>

                <div className="flex items-center gap-2 mt-4 pt-4 border-t border-white/5">
                  <button
                    onClick={() => openEditor(stay)}
                    className="flex-1 flex items-center justify-center gap-2 py-2.5 bg-primary/10 text-primary border border-primary/20 rounded-xl hover:bg-primary/20 transition-all text-xs font-bold uppercase tracking-widest"
                  >
                    <Edit2 className="h-3.5 w-3.5" />
                    Edit Details
                  </button>
                  <a
                    href={`/stays/${stay.id}`}
                    target="_blank"
                    rel="noreferrer"
                    className="flex items-center gap-2 px-4 py-2.5 bg-white/[0.03] text-muted-foreground border border-white/5 rounded-xl hover:text-foreground hover:border-white/10 transition-all text-xs font-bold uppercase tracking-widest"
                  >
                    <Eye className="h-3.5 w-3.5" />
                    Preview
                  </a>
                  <button
                    onClick={() => handleDelete(stay.id)}
                    className="p-2.5 text-muted-foreground hover:text-red-400 hover:bg-red-400/10 border border-white/5 hover:border-red-400/20 rounded-xl transition-all"
                    title="Delete Stay"
                  >
                    <Trash2 className="h-4 w-4" />
                  </button>
                </div>
              </div>
            ))
          )}
        </div>
      </div>
    </div>
  )
}

'use client'

import { useState, useEffect } from 'react'
import { createClientComponentClient } from '@/lib/supabase-client'
import { Plus, X, Upload, Image as ImageIcon } from 'lucide-react'

interface TripFormProps {
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  trip?: any
  onSuccess: () => void
}

export function TripForm({ trip, onSuccess }: TripFormProps) {
  const [loading, setLoading] = useState(false)
  const [uploading, setUploading] = useState(false)
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  const [supabase, setSupabase] = useState<any>(null)
  const [activeSection, setActiveSection] = useState<string>('basic')

  // ─── Basic Info ───
  const [formData, setFormData] = useState({
    name: trip?.name || '',
    tagline: trip?.tagline || '',
    description: trip?.description || '',
    region: trip?.region || '',
    terrain: trip?.terrain || '',
    duration: trip?.duration || 5,
    price: trip?.price || 0,
    group_size: trip?.group_size || 12,
    status: trip?.status || 'published',
    image_url: trip?.image_url || '',
    is_featured: trip?.is_featured || false,
    show_on_all_trips: trip?.show_on_all_trips !== false,
    show_on_journeys: trip?.show_on_journeys || trip?.is_featured || false,
  })

  // ─── Itinerary Days ───
  const [itinerary, setItinerary] = useState<{ day: number; title: string; description: string; image_url: string }[]>(
    trip?.itinerary || [{ day: 1, title: '', description: '', image_url: '' }]
  )

  // ─── Lists ───
  const [inclusions, setInclusions] = useState<string[]>(trip?.inclusions || [''])
  const [exclusions, setExclusions] = useState<string[]>(trip?.exclusions || [''])
  const [terms, setTerms] = useState<string[]>(trip?.terms || [''])
  const [thingsToCarry, setThingsToCarry] = useState<string[]>(trip?.things_to_carry || [''])
  const [dates, setDates] = useState<{ start: string; end: string; spots: number }[]>(
    trip?.dates || [{ start: '', end: '', spots: 10 }]
  )

  useEffect(() => {
    setSupabase(createClientComponentClient())
  }, [])

  useEffect(() => {
    setFormData({
      name: trip?.name || '',
      tagline: trip?.tagline || '',
      description: trip?.description || '',
      region: trip?.region || '',
      terrain: trip?.terrain || '',
      duration: trip?.duration || 5,
      price: trip?.price || 0,
      group_size: trip?.group_size || 12,
      status: trip?.status || 'published',
      image_url: trip?.image_url || '',
      is_featured: trip?.is_featured || false,
      show_on_all_trips: trip?.show_on_all_trips !== false,
      show_on_journeys: trip?.show_on_journeys || trip?.is_featured || false,
    })
    setItinerary(trip?.itinerary || [{ day: 1, title: '', description: '', image_url: '' }])
    setInclusions(trip?.inclusions || [''])
    setExclusions(trip?.exclusions || [''])
    setTerms(trip?.terms || [''])
    setThingsToCarry(trip?.things_to_carry || [''])
  // eslint-disable-next-line react-hooks/exhaustive-deps
  // eslint-disable-next-line react-hooks/exhaustive-deps
    setDates(trip?.dates || [{ start: '', end: '', spots: 10 }])
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [trip?.id])

  // ─── Image Upload ───
  const handleImageUpload = async (file: File, callback: (url: string) => void) => {
    if (!supabase || !file) return
    setUploading(true)
    try {
      const fileExt = file.name.split('.').pop()
      const fileName = `${Date.now()}-${Math.random().toString(36).substring(7)}.${fileExt}`
      const filePath = `trips/${fileName}`

      const { error: uploadError } = await supabase.storage
        .from('images')
        .upload(filePath, file)

      if (uploadError) throw uploadError

      const { data: { publicUrl } } = supabase.storage
        .from('images')
        .getPublicUrl(filePath)

      callback(publicUrl)
    } catch (error: unknown) {
      console.error('Upload error:', error)
      alert(`Upload failed: ${error.message}`)
    } finally {
      setUploading(false)
    }
  }

  // ─── List Helpers ───
  const addListItem = (list: string[], setList: (l: string[]) => void) => setList([...list, ''])
  const removeListItem = (list: string[], setList: (l: string[]) => void, index: number) => setList(list.filter((_, i) => i !== index))
  const updateListItem = (list: string[], setList: (l: string[]) => void, index: number, value: string) => {
    const updated = [...list]
    updated[index] = value
    setList(updated)
  }

  // ─── Submit ───
  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault()
    if (!supabase) return
    setLoading(true)

    try {
      const payload = {
        ...formData,
        is_featured: formData.show_on_journeys,
        itinerary: itinerary.filter(d => d.title.trim()),
        inclusions: inclusions.filter(i => i.trim()),
        exclusions: exclusions.filter(i => i.trim()),
        terms: terms.filter(i => i.trim()),
        things_to_carry: thingsToCarry.filter(i => i.trim()),
        dates: dates.filter(d => d.start.trim()),
      }

      if (trip?.id) {
        const response = await fetch('/api/admin/trips', {
          method: 'PATCH',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ id: trip.id, ...payload }),
        })
        const result = await response.json()
        if (!response.ok) throw new Error(result.error || 'Failed to update trip')
      } else {
        const response = await fetch('/api/admin/trips', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify(payload),
        })
        const result = await response.json()
        if (!response.ok) throw new Error(result.error || 'Failed to create trip')
      }
      onSuccess()
    } catch (error: unknown) {
      console.error('Save error:', error)
      alert(`Error saving trip: ${error.message}`)
    } finally {
      setLoading(false)
    }
  }

  const sections = [
    { id: 'basic', label: 'Basic Info' },
    { id: 'itinerary', label: `Itinerary (${itinerary.length} days)` },
    { id: 'inclusions', label: `Inclusions (${inclusions.filter(i => i.trim()).length})` },
    { id: 'exclusions', label: `Exclusions (${exclusions.filter(i => i.trim()).length})` },
    { id: 'terms', label: `Terms & Conditions (${terms.filter(i => i.trim()).length})` },
    { id: 'carry', label: `Things to Carry (${thingsToCarry.filter(i => i.trim()).length})` },
    { id: 'dates', label: `Dates & Availability (${dates.filter(d => d.start.trim()).length})` },
    { id: 'visibility', label: 'Visibility & Publishing' },
  ]

  const inputClass = "w-full px-4 py-2.5 bg-background border border-muted-foreground/20 rounded-xl text-foreground text-sm focus:border-primary focus:ring-1 focus:ring-primary outline-none transition-all"
  const labelClass = "block text-xs font-semibold text-foreground/80 uppercase tracking-wider mb-1.5"

  return (
    <form onSubmit={handleSubmit} className="bg-card border border-primary/10 rounded-2xl shadow-xl overflow-hidden">
      {/* Section Navigation */}
      <div className="flex flex-wrap gap-1 p-3 bg-background/50 border-b border-muted-foreground/10">
        {sections.map(s => (
          <button
            key={s.id}
            type="button"
            onClick={() => setActiveSection(s.id)}
            className={`px-3 py-1.5 rounded-lg text-xs font-medium transition-all ${activeSection === s.id
              ? 'bg-primary text-primary-foreground shadow-sm'
              : 'text-muted-foreground hover:text-foreground hover:bg-muted-foreground/10'
              }`}
          >
            {s.label}
          </button>
        ))}
      </div>

      <div className="p-6 space-y-6">
        {/* ═══ BASIC INFO ═══ */}
        {activeSection === 'basic' && (
          <div className="space-y-5">
            <div className="grid md:grid-cols-2 gap-5">
              <div>
                <label className={labelClass}>Trip Name *</label>
                <input type="text" value={formData.name} onChange={(e) => setFormData({ ...formData, name: e.target.value })} className={inputClass} required placeholder="e.g. Spiti Valley Expedition" />
              </div>
              <div>
                <label className={labelClass}>Tagline</label>
                <input type="text" value={formData.tagline} onChange={(e) => setFormData({ ...formData, tagline: e.target.value })} className={inputClass} placeholder="e.g. Silence, altitude, and shared roads" />
              </div>
            </div>

            <div>
              <label className={labelClass}>Description / Story</label>
              <textarea value={formData.description} onChange={(e) => setFormData({ ...formData, description: e.target.value })} className={`${inputClass} h-32 resize-y`} placeholder="Tell the story of this journey..." />
            </div>

            <div className="grid md:grid-cols-3 gap-5">
              <div>
                <label className={labelClass}>Region</label>
                <input type="text" value={formData.region} onChange={(e) => setFormData({ ...formData, region: e.target.value })} className={inputClass} placeholder="e.g. Himachal Pradesh" />
              </div>
              <div>
                <label className={labelClass}>Terrain</label>
                <select value={formData.terrain} onChange={(e) => setFormData({ ...formData, terrain: e.target.value })} className={inputClass} required>
                  <option value="">Select terrain</option>
                  <option value="mountains">Mountains</option>
                  <option value="forest">Forest</option>
                  <option value="coast">Coast</option>
                  <option value="desert">Desert</option>
                  <option value="plateaus">Plateaus</option>
                  <option value="valleys">Valleys</option>
                  <option value="mixed">Mixed</option>
                </select>
              </div>
              <div>
                <label className={labelClass}>Duration (Days)</label>
                <input type="number" value={formData.duration} onChange={(e) => setFormData({ ...formData, duration: parseInt(e.target.value) || 0 })} className={inputClass} />
              </div>
            </div>

            <div className="grid md:grid-cols-2 gap-5">
              <div>
                <label className={labelClass}>Price (₹)</label>
                <input type="number" value={formData.price} onChange={(e) => setFormData({ ...formData, price: parseInt(e.target.value) || 0 })} className={inputClass} />
              </div>
              <div>
                <label className={labelClass}>Max Group Size</label>
                <input type="number" value={formData.group_size} onChange={(e) => setFormData({ ...formData, group_size: parseInt(e.target.value) || 0 })} className={inputClass} />
              </div>
            </div>

            {/* Hero Image */}
            <div>
              <label className={labelClass}>Hero Image</label>
              <div className="flex gap-3">
                <input type="url" value={formData.image_url} onChange={(e) => setFormData({ ...formData, image_url: e.target.value })} className={`${inputClass} flex-1`} placeholder="Paste image URL or upload" />
                <label className="flex items-center gap-2 px-4 py-2 bg-primary/10 text-primary rounded-xl cursor-pointer hover:bg-primary/20 transition-all text-sm font-medium">
                  <Upload className="h-4 w-4" />
                  {uploading ? 'Uploading...' : 'Upload'}
                  <input type="file" accept="image/*" className="hidden" onChange={(e) => {
                    const file = e.target.files?.[0]
                    if (file) handleImageUpload(file, (url) => setFormData({ ...formData, image_url: url }))
                  }} />
                </label>
              </div>
              {formData.image_url && (
  // eslint-disable-next-line react/jsx-no-comment-textnodes
                <div className="mt-3 relative w-48 h-32 rounded-xl overflow-hidden border border-muted-foreground/20">
  // eslint-disable-next-line @next/next/no-img-element
  // eslint-disable-next-line @next/next/no-img-element
  // eslint-disable-next-line @next/next/no-img-element
                  <img src={formData.image_url} alt="Preview" className="w-full h-full object-cover" />
                </div>
              )}
            </div>
          </div>
        )}

        {/* ═══ ITINERARY ═══ */}
        {activeSection === 'itinerary' && (
          <div className="space-y-4">
            <p className="text-xs text-muted-foreground">Add each day of the journey with a title, description, and optional image.</p>
            {itinerary.map((day, index) => (
              <div key={index} className="p-4 border border-muted-foreground/10 rounded-xl space-y-3 bg-background/50">
                <div className="flex items-center justify-between">
                  <span className="text-xs font-bold text-primary uppercase tracking-widest">Day {index + 1}</span>
                  {itinerary.length > 1 && (
                    <button type="button" onClick={() => setItinerary(itinerary.filter((_, i) => i !== index))} className="p-1 text-red-400 hover:bg-red-400/10 rounded">
                      <X className="h-4 w-4" />
                    </button>
                  )}
                </div>
                <input type="text" value={day.title} onChange={(e) => { const u = [...itinerary]; u[index].title = e.target.value; setItinerary(u) }} className={inputClass} placeholder="Day title (e.g. Shimla to Narkanda)" />
                <textarea value={day.description} onChange={(e) => { const u = [...itinerary]; u[index].description = e.target.value; setItinerary(u) }} className={`${inputClass} h-20 resize-y`} placeholder="What happens on this day..." />
                <div className="flex gap-3 items-center">
                  <input type="url" value={day.image_url} onChange={(e) => { const u = [...itinerary]; u[index].image_url = e.target.value; setItinerary(u) }} className={`${inputClass} flex-1`} placeholder="Day image URL (optional)" />
                  <label className="flex items-center gap-1 px-3 py-2 bg-primary/10 text-primary rounded-lg cursor-pointer hover:bg-primary/20 transition-all text-xs">
                    <ImageIcon className="h-3 w-3" />
                    Upload
                    <input type="file" accept="image/*" className="hidden" onChange={(e) => {
                      const file = e.target.files?.[0]
                      if (file) handleImageUpload(file, (url) => { const u = [...itinerary]; u[index].image_url = url; setItinerary(u) })
                    }} />
                  </label>
                </div>
              </div>
            ))}
            <button type="button" onClick={() => setItinerary([...itinerary, { day: itinerary.length + 1, title: '', description: '', image_url: '' }])} className="flex items-center gap-2 px-4 py-2 border border-dashed border-primary/30 rounded-xl text-primary text-sm hover:bg-primary/5 transition-all w-full justify-center">
              <Plus className="h-4 w-4" /> Add Day {itinerary.length + 1}
            </button>
          </div>
        )}

        {/* ═══ INCLUSIONS ═══ */}
        {activeSection === 'inclusions' && (
          <ListEditor label="Inclusions" placeholder="e.g. All accommodation" items={inclusions} setItems={setInclusions} addItem={addListItem} removeItem={removeListItem} updateItem={updateListItem} />
        )}

        {/* ═══ EXCLUSIONS ═══ */}
        {activeSection === 'exclusions' && (
          <ListEditor label="Exclusions" placeholder="e.g. Personal expenses" items={exclusions} setItems={setExclusions} addItem={addListItem} removeItem={removeListItem} updateItem={updateListItem} />
        )}

        {/* ═══ TERMS ═══ */}
        {activeSection === 'terms' && (
          <ListEditor label="Terms & Conditions" placeholder="e.g. 50% refund on cancellation 7 days before" items={terms} setItems={setTerms} addItem={addListItem} removeItem={removeListItem} updateItem={updateListItem} />
        )}

        {/* ═══ THINGS TO CARRY ═══ */}
        {activeSection === 'carry' && (
          <ListEditor label="Things to Carry" placeholder="e.g. Warm jacket, sunscreen" items={thingsToCarry} setItems={setThingsToCarry} addItem={addListItem} removeItem={removeListItem} updateItem={updateListItem} />
        )}

        {/* ═══ DATES ═══ */}
        {activeSection === 'dates' && (
          <div className="space-y-4">
            <p className="text-xs text-muted-foreground">Add available travel dates and spots for each batch.</p>
            {dates.map((d, index) => (
              <div key={index} className="grid grid-cols-3 gap-3 items-end">
                <div>
                  <label className={labelClass}>Start Date</label>
                  <input type="text" value={d.start} onChange={(e) => { const u = [...dates]; u[index].start = e.target.value; setDates(u) }} className={inputClass} placeholder="e.g. Jun 15" />
                </div>
                <div>
                  <label className={labelClass}>End Date</label>
                  <input type="text" value={d.end} onChange={(e) => { const u = [...dates]; u[index].end = e.target.value; setDates(u) }} className={inputClass} placeholder="e.g. Jun 23" />
                </div>
                <div className="flex gap-2 items-end">
                  <div className="flex-1">
                    <label className={labelClass}>Spots</label>
                    <input type="number" value={d.spots} onChange={(e) => { const u = [...dates]; u[index].spots = parseInt(e.target.value) || 0; setDates(u) }} className={inputClass} />
                  </div>
                  {dates.length > 1 && <button type="button" onClick={() => setDates(dates.filter((_, i) => i !== index))} className="p-2 text-red-400 hover:bg-red-400/10 rounded-lg mb-0.5"><X className="h-4 w-4" /></button>}
                </div>
              </div>
            ))}
            <button type="button" onClick={() => setDates([...dates, { start: '', end: '', spots: 10 }])} className="flex items-center gap-2 px-4 py-2 border border-dashed border-primary/30 rounded-xl text-primary text-sm hover:bg-primary/5 transition-all w-full justify-center">
              <Plus className="h-4 w-4" /> Add Date Batch
            </button>
          </div>
        )}

        {/* ═══ VISIBILITY ═══ */}
        {activeSection === 'visibility' && (
          <div className="space-y-5">
            <div>
              <label className={labelClass}>Status</label>
              <select value={formData.status} onChange={(e) => setFormData({ ...formData, status: e.target.value })} className={inputClass}>
                <option value="draft">Draft (Hidden)</option>
                <option value="published">Published (Live)</option>
                <option value="archived">Archived</option>
              </select>
            </div>

            <div className="space-y-3">
              <label className="flex items-center gap-3 p-4 bg-primary/5 border border-primary/20 rounded-xl cursor-pointer hover:bg-primary/10 transition-all">
                <input type="checkbox" checked={formData.show_on_all_trips} onChange={(e) => setFormData({ ...formData, show_on_all_trips: e.target.checked })} className="w-5 h-5 accent-primary" />
                <div>
                  <span className="text-sm font-semibold text-foreground">Show on All Trips Page</span>
                  <p className="text-xs text-muted-foreground mt-0.5">Trip appears on the /all-trips browsing page</p>
                </div>
              </label>

              <label className="flex items-center gap-3 p-4 bg-emerald-500/5 border border-emerald-500/20 rounded-xl cursor-pointer hover:bg-emerald-500/10 transition-all">
                <input type="checkbox" checked={formData.show_on_journeys} onChange={(e) => setFormData({ ...formData, show_on_journeys: e.target.checked })} className="w-5 h-5 accent-emerald-500" />
                <div>
                  <span className="text-sm font-semibold text-foreground">Show on Journeys Page</span>
                  <p className="text-xs text-muted-foreground mt-0.5">Featured on the curated /journeys page</p>
                </div>
              </label>
            </div>
          </div>
        )}
      </div>

      {/* Submit */}
      <div className="p-6 border-t border-muted-foreground/10 bg-background/30">
        <button type="submit" disabled={loading} className="w-full py-4 bg-primary text-background rounded-xl hover:bg-primary/90 transition-all font-sans font-bold shadow-lg shadow-primary/20 disabled:opacity-50 active:scale-[0.98]">
          {loading ? 'Saving to Supabase...' : trip ? 'Update Expedition' : 'Create New Expedition'}
        </button>
      </div>
    </form>
  )
}

// ─── Reusable List Editor ───
function ListEditor({ label, placeholder, items, setItems, addItem, removeItem, updateItem }: {
  label: string; placeholder: string; items: string[]; setItems: (l: string[]) => void;
  addItem: (l: string[], s: (l: string[]) => void) => void;
  removeItem: (l: string[], s: (l: string[]) => void, i: number) => void;
  updateItem: (l: string[], s: (l: string[]) => void, i: number, v: string) => void;
}) {
  return (
    <div className="space-y-3">
      <p className="text-xs text-muted-foreground">Add each {label.toLowerCase()} item. These appear as bullet points on the trip detail page.</p>
      {items.map((item, index) => (
        <div key={index} className="flex gap-2">
          <input type="text" value={item} onChange={(e) => updateItem(items, setItems, index, e.target.value)} className="w-full px-4 py-2.5 bg-background border border-muted-foreground/20 rounded-xl text-foreground text-sm focus:border-primary focus:ring-1 focus:ring-primary outline-none transition-all" placeholder={placeholder} />
          {items.length > 1 && <button type="button" onClick={() => removeItem(items, setItems, index)} className="p-2 text-red-400 hover:bg-red-400/10 rounded-lg"><X className="h-4 w-4" /></button>}
        </div>
      ))}
      <button type="button" onClick={() => addItem(items, setItems)} className="flex items-center gap-2 px-4 py-2 border border-dashed border-primary/30 rounded-xl text-primary text-sm hover:bg-primary/5 transition-all w-full justify-center">
        <Plus className="h-4 w-4" /> Add {label} Item
      </button>
    </div>
  )
}

'use client'

import { useState, useEffect } from 'react'
import { Plus, Edit2, Trash2, Globe, Users, Clock, MapPin, Eye } from 'lucide-react'
import { TripForm } from './trip-form'

export function TripsManager() {
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  const [trips, setTrips] = useState<any[]>([])
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState<string | null>(null)
  const [showForm, setShowForm] = useState(false)
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  const [editingTrip, setEditingTrip] = useState<any>(null)
  const [activeTab, setActiveTab] = useState<'published' | 'draft' | 'archived'>('published')

  useEffect(() => {
    fetchTrips()
  }, [])

  const fetchTrips = async () => {
    setLoading(true)
    setError(null)
    try {
      const response = await fetch('/api/admin/trips', { cache: 'no-store' })
      const result = await response.json()

      if (!response.ok) {
        throw new Error(result.error || 'Failed to load trips')
      }

      setTrips(result.data || [])
    } catch (err: unknown) {
      console.error('Trips fetch error:', err)
      setTrips([])
      setError((err as Error)?.message || 'Failed to load trips')
    } finally {
      setLoading(false)
    }
  }

  const handleDelete = async (id: string) => {
    if (confirm('Delete this trip? This action cannot be undone.')) {
      try {
        const response = await fetch(`/api/admin/trips?id=${id}`, { method: 'DELETE' })
        const result = await response.json()

        if (!response.ok) {
          throw new Error(result.error || 'Failed to delete trip')
        }

        fetchTrips()
      } catch (err: unknown) {
        setError((err as Error)?.message || 'Failed to delete trip')
      }
    }
  }

  return (
    <div className="space-y-8">
      {/* Header with Add Button */}
      <div className="flex flex-col sm:flex-row items-start sm:items-center justify-between gap-4">
        <h2 className="font-serif text-2xl text-foreground">Expeditions Cache</h2>
        <button
          onClick={() => {
            setEditingTrip(null)
            setShowForm(!showForm)
          }}
          className={`flex items-center gap-2 px-6 py-2.5 rounded-xl transition-all font-sans font-semibold text-sm shadow-lg ${showForm
            ? 'bg-muted-foreground/10 text-muted-foreground'
            : 'bg-primary text-background hover:bg-primary/90 shadow-primary/20'
            }`}
        >
          <Plus className={`h-4 w-4 transition-transform duration-300 ${showForm ? 'rotate-45' : ''}`} />
          {showForm ? 'Close Editor' : 'Direct New Expedition'}
        </button>
      </div>

      {/* Trip Form */}
      <div className={`transition-all duration-500 ease-in-out overflow-hidden ${showForm ? 'max-h-[3000px] opacity-100 mb-12' : 'max-h-0 opacity-0 pointer-events-none'
        }`}>
        <TripForm
          trip={editingTrip}
          onSuccess={() => {
            setShowForm(false)
            fetchTrips()
          }}
        />
      </div>

      {error && (
        <div className="rounded-xl border border-red-500/20 bg-red-500/10 px-4 py-3 text-sm text-red-300">
          {error}
        </div>
      )}

      {/* Tabs */}
      {!loading && trips.length > 0 && (
        <div className="flex items-center gap-4 border-b border-muted-foreground/10 pb-4 mb-6 overflow-x-auto whitespace-nowrap scrollbar-hide">
          {(['published', 'draft', 'archived'] as const).map((tab) => {
            const count = trips.filter(t => (t.status || 'draft') === tab).length
            return (
              <button
                key={tab}
                onClick={() => setActiveTab(tab)}
                className={`relative pb-4 -mb-[17px] text-sm font-sans font-semibold transition-colors
                  ${activeTab === tab ? 'text-primary' : 'text-muted-foreground hover:text-foreground'}
                `}
              >
                <span className="capitalize">{tab}</span>
                <span className="ml-2 text-[10px] bg-muted-foreground/10 px-2 py-0.5 rounded-full">{count}</span>
                {activeTab === tab && (
                  <div className="absolute bottom-0 left-0 right-0 h-0.5 bg-primary rounded-t-full shadow-[0_-2px_8px_rgba(var(--primary),0.5)]" />
                )}
              </button>
            )
          })}
        </div>
      )}

      {/* Trips Grid */}
      <div className="grid gap-4">
        {loading ? (
          <div className="py-20 text-center text-muted-foreground animate-pulse font-sans">Syncing with satellite data...</div>
        ) : trips.length === 0 ? (
          <div className="py-20 text-center border-2 border-dashed border-muted-foreground/10 rounded-2xl">
            <p className="font-sans text-muted-foreground italic">No expeditions recorded. Click the button above to begin.</p>
          </div>
        ) : trips.filter(t => (t.status || 'draft') === activeTab).length === 0 ? (
          <div className="py-20 text-center border-2 border-dashed border-muted-foreground/10 rounded-2xl">
            <p className="font-sans text-muted-foreground italic">No {activeTab} expeditions found.</p>
          </div>
        ) : (
          trips
            .filter(t => (t.status || 'draft') === activeTab)
            .map((trip) => (
              <div
                key={trip.id}
                className="p-4 sm:p-6 bg-card border border-primary/5 rounded-2xl flex flex-col md:flex-row md:items-center justify-between gap-4 sm:gap-6 hover:shadow-xl hover:border-primary/20 transition-all group"
              >
                <div className="flex flex-col sm:flex-row gap-4 items-start flex-1">
                  {trip.image_url && (
  // eslint-disable-next-line react/jsx-no-comment-textnodes
                    <div className="w-full sm:w-20 h-40 sm:h-20 rounded-xl overflow-hidden shrink-0 border border-muted-foreground/10">
  // eslint-disable-next-line @next/next/no-img-element
  // eslint-disable-next-line @next/next/no-img-element
  // eslint-disable-next-line @next/next/no-img-element
                      <img src={trip.image_url} alt={trip.name} className="w-full h-full object-cover" />
                    </div>
                  )}
                  <div className="space-y-3">
                    <div className="flex items-center gap-3">
                      <h3 className="font-serif text-xl text-foreground group-hover:text-primary transition-colors">{trip.name || trip.title}</h3>
                      <span className={`text-[10px] uppercase font-bold tracking-widest px-2 py-0.5 rounded ${trip.status === 'published' ? 'bg-green-500/10 text-green-400' : 'bg-yellow-500/10 text-yellow-500'
                        }`}>
                        {trip.status}
                      </span>
                    </div>

                    <div className="flex flex-wrap items-center gap-3 text-xs text-muted-foreground uppercase tracking-widest">
                      <div className="flex items-center gap-1.5 bg-muted-foreground/5 px-2 py-1 rounded">
                        <Clock className="h-3 w-3" />
                        {trip.duration} Days
                      </div>
                      <div className="flex items-center gap-1.5 bg-muted-foreground/5 px-2 py-1 rounded">
                        <Users className="h-3 w-3" />
                        Max {trip.group_size}
                      </div>
                      <div className="flex items-center gap-1.5 bg-muted-foreground/5 px-2 py-1 rounded">
                        <Globe className="h-3 w-3" />
                        {trip.region || 'Remote'}
                      </div>
                      <div className="font-sans font-bold text-foreground bg-primary/10 px-2 py-1 rounded text-primary">
                        ₹{trip.price?.toLocaleString()}
                      </div>
                    </div>

                    {/* Visibility Badges */}
                    <div className="flex flex-wrap gap-2">
                      {trip.show_on_all_trips !== false && (
                        <span className="flex items-center gap-1 px-2 py-0.5 bg-blue-500/10 text-blue-400 rounded text-[10px] font-semibold uppercase tracking-wider">
                          <Eye className="h-3 w-3" /> All Trips
                        </span>
                      )}
                      {trip.is_featured && (
                        <span className="flex items-center gap-1 px-2 py-0.5 bg-emerald-500/10 text-emerald-400 rounded text-[10px] font-semibold uppercase tracking-wider">
                          <MapPin className="h-3 w-3" /> Journeys
                        </span>
                      )}
                      {trip.itinerary && trip.itinerary.length > 0 && (
                        <span className="px-2 py-0.5 bg-purple-500/10 text-purple-400 rounded text-[10px] font-semibold uppercase tracking-wider">
                          {trip.itinerary.length}-Day Itinerary
                        </span>
                      )}
                      {trip.inclusions && trip.inclusions.length > 0 && (
                        <span className="px-2 py-0.5 bg-amber-500/10 text-amber-400 rounded text-[10px] font-semibold uppercase tracking-wider">
                          {trip.inclusions.length} Inclusions
                        </span>
                      )}
                    </div>
                  </div>
                </div>

                <div className="flex items-center gap-3 border-t md:border-t-0 pt-4 md:pt-0 border-muted-foreground/10">
                  <button
                    onClick={() => {
                      setEditingTrip(trip)
                      setShowForm(true)
                    }}
                    className="flex-1 md:flex-none flex items-center justify-center gap-2 px-4 py-2 bg-background border border-muted-foreground/20 rounded-lg hover:border-primary/50 transition-all font-sans text-xs font-semibold"
                  >
                    <Edit2 className="h-3.5 w-3.5" />
                    Edit
                  </button>
                  <button
                    onClick={() => handleDelete(trip.id)}
                    className="p-2.5 text-muted-foreground hover:text-red-400 hover:bg-red-400/10 rounded-lg transition-all"
                    title="Archive/Delete Expedition"
                  >
                    <Trash2 className="h-4 w-4" />
                  </button>
                </div>
              </div>
            ))
        )}
      </div>
    </div>
  )
}

"use client"

import { useState, useEffect, useMemo, useRef } from 'react'
import { motion, AnimatePresence, useScroll, useTransform } from 'framer-motion'
import Image from 'next/image'
import { ChevronDown, Search } from 'lucide-react'
import { Navbar } from '../ui/navbar'
import { TripGridCard } from './trip-grid-card'
import { TripFilters } from './trip-filters'
import { Footer } from '../ui/footer'
import { Magnetic } from '../ui/magnetic'

const transition = {
  duration: 1.2,
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  ease: [0.23, 1, 0.32, 1] as any,
}

  // eslint-disable-next-line @typescript-eslint/no-explicit-any
export function AllTripsDynamic({ initialTrips = [] }: { initialTrips?: any[] }) {
  // eslint-disable-next-line unused-imports/no-unused-vars
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  const [trips, setTrips] = useState<any[]>(initialTrips)
  const [filtersExpanded, setFiltersExpanded] = useState(false)
  const [moodSearch, setMoodSearch] = useState('')
  const [filters, setFilters] = useState({
    region: 'all',
    terrain: 'all',
    duration: 'all',
  })
  // eslint-disable-next-line unused-imports/no-unused-vars
  const [mounted, setMounted] = useState(false)
  const headerRef = useRef<HTMLElement>(null)

  const { scrollYProgress } = useScroll({
    target: headerRef,
    offset: ["start start", "end start"]
  })

  const headerY = useTransform(scrollYProgress, [0, 1], [0, -50])
  const headerOpacity = useTransform(scrollYProgress, [0, 0.8], [1, 0])

  useEffect(() => {
    setMounted(true)
  }, [])

  const filteredTrips = useMemo(() => {
    return trips.filter((trip) => {
      if (filters.region !== 'all' && trip.region !== filters.region) return false
      if (filters.terrain !== 'all' && trip.terrain !== filters.terrain) return false
      if (filters.duration !== 'all') {
        const days = Number.parseInt(trip.duration?.toString() || '0')
        if (filters.duration === 'short' && days > 7) return false
        if (filters.duration === 'long' && days <= 7) return false
      }
      if (moodSearch && !trip.name?.toLowerCase().includes(moodSearch.toLowerCase())) return false
      return true
    })
  }, [trips, filters, moodSearch])

  return (
    <main className="relative min-h-screen bg-background overflow-x-hidden">
      <Navbar visible={true} />

      {/* Decorative Grain Overlay */}
      <div className="fixed inset-0 pointer-events-none z-50 opacity-[0.03] grayscale" style={{ backgroundImage: "url('/noise.png')" }} />

      {/* Cinematic Header Section */}
      <section ref={headerRef} className="relative px-6 pt-56 pb-20 md:px-16 lg:px-24 overflow-hidden min-h-[80vh] flex items-center">
        {/* Background Depth */}
        <div className="absolute inset-0 z-0">
          <Image 
            src="/hero1.png" 
            alt="Catalog Background" 
            fill 
            className="object-cover opacity-20 blur-2xl scale-110" 
            priority
          />
          <div className="absolute inset-0 bg-gradient-to-b from-background via-transparent to-background" />
        </div>

        <motion.div
          style={{ y: headerY, opacity: headerOpacity }}
          className="relative z-10 mx-auto max-w-5xl"
        >
          <motion.span 
            initial={{ opacity: 0, y: 10 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ ...transition, delay: 0.1 }}
            className="text-[10px] uppercase tracking-[0.6em] text-primary/60 font-bold mb-8 block"
          >
            The Catalog
          </motion.span>
          <motion.h1 
            initial={{ opacity: 0, scale: 0.95, filter: "blur(10px)" }}
            animate={{ opacity: 1, scale: 1, filter: "blur(0px)" }}
            transition={{ duration: 1.5, ease: [0.23, 1, 0.32, 1] }}
            className="font-serif text-[clamp(2.5rem,10vw,7.5rem)] leading-[0.85] text-foreground tracking-tightest"
          >
            Every journey <br />
            <span className="text-foreground/40 italic">we currently run.</span>
          </motion.h1>
          <motion.p 
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ ...transition, delay: 0.8 }}
            className="mt-12 font-serif text-2xl md:text-3xl text-muted-foreground/60 lowercase italic max-w-2xl leading-relaxed"
          >
            Different places. same pace. A collection of moments <br className="hidden md:block" /> waiting for the right souls.
          </motion.p>
        </motion.div>
      </section>

      {/* Discovery Bar - Magnetic & Glassmorphic */}
      <section className="px-6 py-12 md:px-16 lg:px-24 sticky top-0 z-40">
        <div className="mx-auto max-w-5xl">
          <Magnetic strength={0.1}>
            <motion.div 
                initial={{ opacity: 0, scale: 0.98 }}
                animate={{ opacity: 1, scale: 1 }}
                transition={{ ...transition, delay: 1 }}
                className="group relative flex items-center glass rounded-full px-8 py-5 shadow-sm md:shadow-md dark:shadow-2xl hover:bg-muted dark:hover:bg-white/[0.03] transition-all duration-500 inner-glow"
            >
                <Search className="w-5 h-5 text-primary/40 mr-6 group-focus-within:text-primary transition-colors" />
                <input
                type="text"
                value={moodSearch}
                onChange={(e) => setMoodSearch(e.target.value)}
                placeholder="Filter by terrain, vibe, or destination..."
                className="w-full bg-transparent font-sans text-xs md:text-sm text-foreground placeholder:text-muted-foreground/20 focus:outline-none tracking-[0.3em] uppercase font-bold"
                />
                <div className="flex items-center gap-6 ml-4 border-l border-white/5 pl-6">
                <button
                    onClick={() => setFiltersExpanded(!filtersExpanded)}
                    className="flex items-center gap-3 text-muted-foreground/40 hover:text-foreground transition-all"
                >
                    <div className={`transition-transform duration-700 ease-apple-ease ${filtersExpanded ? 'rotate-180' : ''}`}>
                    <ChevronDown className="h-4 w-4" />
                    </div>
                </button>
                </div>
            </motion.div>
          </Magnetic>

          <AnimatePresence>
            {filtersExpanded && (
              <motion.div
                initial={{ height: 0, opacity: 0, y: -20 }}
                animate={{ height: "auto", opacity: 1, y: 0 }}
                exit={{ height: 0, opacity: 0, y: -20 }}
                transition={{ duration: 0.8, ease: [0.23, 1, 0.32, 1] }}
                className="overflow-hidden mt-6"
              >
                <div className="glass rounded-[2rem] p-10 mb-4 inner-glow">
                  <TripFilters activeFilters={filters} onFilterChange={setFilters} />
                </div>
              </motion.div>
            )}
          </AnimatePresence>
        </div>
      </section>

      {/* Bento Discovery Grid */}
      <section className="px-6 py-24 md:px-16 lg:px-24 pb-48">
        <div className="mx-auto max-w-[1400px]">
          <AnimatePresence mode="popLayout">
            {filteredTrips.length === 0 ? (
                <motion.div 
                key="no-results"
                initial={{ opacity: 0, y: 20 }}
                animate={{ opacity: 1, y: 0 }}
                exit={{ opacity: 0, scale: 0.95 }}
                className="text-center py-48 rounded-[3rem] glass inner-glow"
                >
                <p className="font-serif text-3xl text-muted-foreground/40 italic">No journeys matched your vibe.</p>
                <button 
                    onClick={() => { setFilters({ region: 'all', terrain: 'all', duration: 'all' }); setMoodSearch('') }}
                    className="mt-8 text-primary uppercase tracking-[0.4em] text-[10px] font-bold border border-primary/20 px-8 py-3 rounded-full hover:bg-primary/5 transition-all"
                >
                    Reset Curiosity
                </button>
                </motion.div>
            ) : (
                <motion.div 
                    key="results"
                    initial={{ opacity: 0 }}
                    animate={{ opacity: 1 }}
                    transition={{ staggerChildren: 0.1 }}
                    className="grid gap-6 md:grid-cols-12 auto-rows-[300px] md:auto-rows-[450px]"
                >
                {filteredTrips.map((trip, index) => {
                    const mod = index % 6;
                    let gridClass = "md:col-span-4 md:row-span-1";
                    let featured = false;

                    if (mod === 0) { gridClass = "md:col-span-8 md:row-span-2"; featured = true; }
                    else if (mod === 1) { gridClass = "md:col-span-4 md:row-span-1"; }
                    else if (mod === 2) { gridClass = "md:col-span-4 md:row-span-2"; }
                    else if (mod === 3) { gridClass = "md:col-span-4 md:row-span-1"; }
                    else if (mod === 4) { gridClass = "md:col-span-8 md:row-span-1"; }
                    else if (mod === 5) { gridClass = "md:col-span-4 md:row-span-1"; }

                    const mappedTrip = {
                    ...trip,
                    name: trip.name || trip.title,
                    image: trip.image_url || trip.image || "/placeholder.jpg",
                    groupSize: trip.group_size || "8-10"
                    };

                    return (
                    <motion.div 
                        key={trip.id}
                        layout
                        initial={{ opacity: 0, y: 30 }}
                        whileInView={{ opacity: 1, y: 0 }}
                        viewport={{ once: true }}
                        transition={{ duration: 1, ease: [0.23, 1, 0.32, 1], delay: index * 0.05 }}
                        className={`${gridClass}`}
                    >
                        <TripGridCard trip={mappedTrip} index={index} featured={featured} />
                    </motion.div>
                    );
                })}
                </motion.div>
            )}
          </AnimatePresence>
        </div>
      </section>

      <Footer />
    </main>
  )
}

'use client'

import { useState, useEffect } from 'react'
import Image from 'next/image'
import { Heart, MessageCircle, Send } from 'lucide-react'
import { createClientComponentClient } from '@/lib/supabase-client'
import { useRouter } from 'next/navigation'

interface Story {
  id: string
  traveller: string
  trip: string
  duration: string
  image: string
  quote: string
  date: string
  likes: number
  comments: number
  isLiked?: boolean
}

const staticStories: Story[] = [
  {
    id: '1',
    traveller: 'Apoorva H',
    trip: 'Tawang',
    duration: '7 days',
    image: '/images/offthetrail1.jpeg',
    quote: 'Went solo, came back with a family. Still text the group daily.',
    date: 'Feb 2025',
    likes: 342,
    comments: 28,
  },
  {
    id: '2',
    traveller: 'Shreeram H',
    trip: 'Meghalaya',
    duration: '5 days',
    image: '/images/offthetrail3.jpeg',
    quote: 'We booked for us two. Left with 6 friends planning the next trip.',
    date: 'Jan 2025',
    likes: 521,
    comments: 45,
  },
  {
    id: '3',
    traveller: 'Prashansa R',
    trip: 'Ladakh Roads',
    duration: '10 days',
    image: '/images/offthetrail5.jpeg',
    quote: '3,700 meters up. Lowest I\'ve ever felt anxiety. Highest I\'ve ever felt free.',
    date: 'Dec 2024',
    likes: 798,
    comments: 67,
  },
]

export function TravellerStories() {
  const [stories, setStories] = useState<Story[]>(staticStories)
  const [selectedStory, setSelectedStory] = useState<Story | null>(null)
  const [commentText, setCommentText] = useState("")
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  const [user, setUser] = useState<any>(null)
  const supabase = createClientComponentClient()
  const router = useRouter()

  useEffect(() => {
    const checkUser = async () => {
      try {
        const supabase = createClientComponentClient()
        if (!supabase) return
        const { data: { user } } = await supabase.auth.getUser()
        setUser(user)
  // eslint-disable-next-line unused-imports/no-unused-vars
      } catch (err) {
        // Silently fail as stories are still visible to non-logged-in users
        console.log("Supabase connectivity restricted (Stories)")
      }
    }
    checkUser()
  // eslint-disable-next-line react-hooks/exhaustive-deps
  // eslint-disable-next-line react-hooks/exhaustive-deps
    fetchInteractions()
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [])

  const fetchInteractions = async () => {
    if (!supabase) return
    // In a real app, we'd fetch counts from the DB. For now, let's just use static + local state
  }

  const handleLike = async (storyId: string) => {
    if (!user) {
      router.push('/login')
      return
    }

    // Optimistic update
    setStories(prev => prev.map(s => {
      if (s.id === storyId) {
        return {
          ...s,
          likes: s.isLiked ? s.likes - 1 : s.likes + 1,
          isLiked: !s.isLiked
        }
      }
      return s
    }))

    if (!supabase) return
    if (!selectedStory?.isLiked) {
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
      await (supabase.from('story_likes' as any).upsert({ user_id: user.id, story_id: storyId } as any) as any)
    } else {
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
      await (supabase.from('story_likes' as any).delete().eq('user_id', user.id).eq('story_id', storyId) as any)
    }
  }

  const handleComment = async (e: React.FormEvent) => {
    e.preventDefault()
    if (!user) {
      router.push('/login')
      return
    }
    if (!commentText.trim() || !selectedStory) return

    // Optimistic update
    setStories(prev => prev.map(s => {
      if (s.id === selectedStory.id) {
        return { ...s, comments: s.comments + 1 }
      }
      return s
    }))

    if (supabase) {
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
      await (supabase.from('story_comments' as any).insert({
        user_id: user.id,
        story_id: selectedStory.id,
        content: commentText
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
      } as any) as any)
    }

    setCommentText("")
    // Maybe show a "Comment posted!" toast?
  }

  return (
    <section className="py-24 px-6 md:px-16 lg:px-24">
      <div className="mx-auto max-w-6xl">
        <h2 className="font-serif text-3xl md:text-4xl text-foreground mb-4">Stories from the road</h2>
        <p className="font-sans text-muted-foreground max-w-2xl mb-12">
          Real moments. Real connections. Real lives changed.
        </p>

        <div className="grid md:grid-cols-3 gap-6">
          {stories.map((story) => (
            <div
              key={story.id}
              className="group cursor-pointer"
              onClick={() => setSelectedStory(story)}
            >
              <div className="relative aspect-square overflow-hidden rounded-lg mb-4 bg-card">
                <Image
                  src={story.image}
                  alt={story.traveller}
                  fill
                  className="object-cover group-hover:scale-105 transition-transform duration-300"
                  sizes="(max-width: 768px) 100vw, (max-width: 1200px) 33vw, 400px"
                  quality={85}
                />
                <div className="absolute inset-0 bg-gradient-to-t from-background/80 via-transparent to-transparent opacity-0 group-hover:opacity-100 transition-opacity duration-300" />
              </div>

              <div className="space-y-3">
                <div>
                  <p className="font-sans font-semibold text-foreground">{story.traveller}</p>
                  <p className="font-sans text-xs text-muted-foreground">{story.trip} • {story.duration}</p>
                </div>

                <p className="font-sans text-sm text-muted-foreground italic group-hover:text-foreground transition-colors">
  // eslint-disable-next-line react/no-unescaped-entities
                  "{story.quote}"
                </p>

                <div className="flex items-center gap-4 text-xs text-muted-foreground pt-3 border-t border-muted-foreground/10">
                  <span className={`flex items-center gap-1 transition-colors ${story.isLiked ? 'text-primary' : ''}`}>
                    <Heart className={`h-4 w-4 ${story.isLiked ? 'fill-current' : ''}`} />
                    {story.likes}
                  </span>
                  <span className="flex items-center gap-1">
                    <MessageCircle className="h-4 w-4" />
                    {story.comments}
                  </span>
                  <span className="ml-auto">{story.date}</span>
                </div>
              </div>
            </div>
          ))}
        </div>

        {selectedStory && (
          <div className="fixed inset-0 z-50 flex items-center justify-center bg-background/80 backdrop-blur-sm p-4" onClick={() => setSelectedStory(null)}>
            <div className="bg-card border border-primary/20 rounded-2xl max-w-2xl w-full p-8 shadow-2xl relative" onClick={(e) => e.stopPropagation()}>
              <div className="flex justify-between items-start mb-6">
                <div>
                  <p className="font-sans font-semibold text-foreground text-lg">{selectedStory.traveller}</p>
                  <p className="font-sans text-sm text-muted-foreground">{selectedStory.trip} • {selectedStory.date}</p>
                </div>
                <button onClick={() => setSelectedStory(null)} className="h-8 w-8 flex items-center justify-center rounded-full hover:bg-muted-foreground/10 transition-colors">×</button>
              </div>

              <div className="relative aspect-video overflow-hidden rounded-xl mb-6">
                <Image
                  src={selectedStory.image}
                  alt={selectedStory.traveller}
                  fill
                  className="object-cover"
                />
              </div>

  // eslint-disable-next-line react/no-unescaped-entities
              <p className="font-serif text-xl text-foreground mb-8 leading-relaxed">"{selectedStory.quote}"</p>

              <div className="space-y-6">
                <div className="flex gap-4">
                  <button
                    onClick={() => handleLike(selectedStory.id)}
                    className={`flex-1 flex items-center justify-center gap-2 px-4 py-3 rounded-xl font-sans text-sm transition-all ${selectedStory.isLiked
                      ? 'bg-primary text-background'
                      : 'bg-primary/10 text-primary hover:bg-primary/20'
                      }`}
                  >
                    <Heart className={`h-4 w-4 ${selectedStory.isLiked ? 'fill-current' : ''}`} />
                    {selectedStory.isLiked ? 'Liked' : 'Like'}
                  </button>
                  <div className="flex-[2] relative">
                    <form onSubmit={handleComment} className="relative">
                      <input
                        type="text"
                        placeholder="Share your thoughts..."
                        value={commentText}
                        onChange={(e) => setCommentText(e.target.value)}
                        className="w-full px-4 py-3 pr-12 rounded-xl bg-background border border-muted-foreground/20 text-sm focus:outline-none focus:border-primary transition-colors"
                      />
                      <button
                        type="submit"
                        className="absolute right-2 top-1/2 -translate-y-1/2 p-2 text-primary hover:text-primary/80 transition-colors"
                      >
                        <Send className="h-4 w-4" />
                      </button>
                    </form>
                  </div>
                </div>
              </div>
            </div>
          </div>
        )}
      </div>
    </section>
  )
}

"use client"

import { useEffect, useMemo, useState } from "react"
import { motion, AnimatePresence } from "framer-motion"
import { Search, Calendar as CalendarIcon, Users, MapPin, Sparkles, Navigation, X } from "lucide-react"
import { Popover, PopoverContent, PopoverTrigger } from "@/components/ui/popover"
import { Calendar } from "@/components/ui/calendar"
import { format } from "date-fns"
import { DateRange } from "react-day-picker"
import { useRouter } from "next/navigation"
import {
  DISCOVERY_COPY,
  NORTHEAST_DESTINATIONS,
  NORTHEAST_MOODS,
} from "@/lib/pms/discovery-data"

type ProductType = "stays" | "trips" | "both"

const searchPlaceholders = {
  stays: DISCOVERY_COPY.placeholders.stays,
  trips: DISCOVERY_COPY.placeholders.trips,
  both: DISCOVERY_COPY.placeholders.both,
}

export function DiscoveryConsole() {
  const router = useRouter()
  const [productType, setProductType] = useState<ProductType>("both")
  const [isSearchFocused, setIsSearchFocused] = useState(false)
  const [searchQuery, setSearchQuery] = useState("")
  const [selectedDestination, setSelectedDestination] = useState("")
  const [selectedMood, setSelectedMood] = useState("")
  const [date, setDate] = useState<DateRange | undefined>()
  const [isCalendarOpen, setIsCalendarOpen] = useState(false)
  const [travelers, setTravelers] = useState(1)
  const [isTravelerOpen, setIsTravelerOpen] = useState(false)
  const [placeholderIndex, setPlaceholderIndex] = useState(0)

  const activePlaceholders = searchPlaceholders[productType]
  const activeMood = useMemo(
    () => NORTHEAST_MOODS.find((mood) => mood.tag === selectedMood) ?? null,
    [selectedMood],
  )

  useEffect(() => {
    const timer = setInterval(() => {
      setPlaceholderIndex((prev) => (prev + 1) % activePlaceholders.length)
    }, 3500)

    return () => clearInterval(timer)
  }, [activePlaceholders.length, productType])

  const handleSearch = () => {
    const params = new URLSearchParams()

    if (productType !== "both") params.set("type", productType)
    if (searchQuery) params.set("q", searchQuery)
    if (selectedDestination) params.set("destination", selectedDestination)
    if (selectedMood) params.set("mood", selectedMood)
    if (date?.from) params.set("from", format(date.from, "yyyy-MM-dd"))
    if (date?.to) params.set("to", format(date.to, "yyyy-MM-dd"))
    if (travelers > 1) params.set("travelers", travelers.toString())

    router.push(`/all-trips?${params.toString()}`)
  }

  return (
    <div className="relative z-40 flex w-full max-w-2xl flex-col gap-4">
      <div className="flex w-fit items-center gap-1 rounded-full border border-white/5 bg-[#141414] p-1 shadow-[0_8px_30px_rgba(0,0,0,0.12)]">
        {(["stays", "trips", "both"] as const).map((type) => (
          <button
            key={type}
            onClick={() => setProductType(type)}
            className={`relative z-10 rounded-full px-5 py-2 text-sm font-medium transition-colors ${
              productType === type
                ? "text-foreground"
                : "text-muted-foreground hover:text-foreground/80"
            }`}
          >
            {productType === type && (
              <motion.div
                layoutId="activeTab"
                className="absolute inset-0 -z-10 rounded-full bg-white/10"
                transition={{ type: "spring", stiffness: 400, damping: 30 }}
              />
            )}
            <span className="capitalize">{type}</span>
          </button>
        ))}
      </div>

      <motion.div
        layout
        className="relative flex flex-col divide-y divide-white/5 rounded-[2rem] border border-white/10 bg-[#141414] shadow-[0_8px_30px_rgba(0,0,0,0.12)]"
      >
        <div className="relative flex items-center p-2 pl-4">
          <Search
            className={`h-5 w-5 transition-colors ${
              isSearchFocused ? "text-primary" : "text-muted-foreground"
            }`}
          />
          <div className="relative mx-3 flex h-12 flex-1 items-center overflow-hidden">
            <AnimatePresence mode="wait">
              {!searchQuery && !isSearchFocused && (
                <motion.div
                  key={`${productType}-${placeholderIndex}`}
                  initial={{ opacity: 0, y: 10 }}
                  animate={{ opacity: 1, y: 0 }}
                  exit={{ opacity: 0, y: -10 }}
                  transition={{ duration: 0.3 }}
                  className="pointer-events-none absolute inset-0 flex items-center text-base font-serif italic text-muted-foreground/60"
                >
                  {activePlaceholders[placeholderIndex]}
                </motion.div>
              )}
            </AnimatePresence>
            <input
              type="text"
              value={searchQuery}
              onChange={(event) => setSearchQuery(event.target.value)}
              onFocus={() => setIsSearchFocused(true)}
              onBlur={() => setTimeout(() => setIsSearchFocused(false), 200)}
              className="h-full w-full border-none bg-transparent text-base text-foreground outline-none placeholder-transparent"
              placeholder={activePlaceholders[placeholderIndex]}
            />
            {searchQuery && (
              <button
                onClick={() => setSearchQuery("")}
                className="absolute right-0 rounded-full bg-white/5 p-1 text-muted-foreground hover:text-foreground"
              >
                <X className="h-3 w-3" />
              </button>
            )}
          </div>

          <AnimatePresence>
            {isSearchFocused && (
              <motion.div
                initial={{ opacity: 0, y: 5 }}
                animate={{ opacity: 1, y: 0 }}
                exit={{ opacity: 0, y: 5 }}
                transition={{ duration: 0.2 }}
                className="no-scrollbar absolute left-0 right-0 top-[calc(100%+8px)] z-50 max-h-[60vh] overflow-y-auto rounded-2xl border border-white/10 bg-[#141414] p-4 shadow-2xl"
              >
                {!searchQuery ? (
                  <div className="space-y-6">
                    <div>
                      <p className="mb-3 flex items-center gap-2 text-[10px] uppercase tracking-widest text-muted-foreground/60">
                        <Sparkles className="h-3 w-3 text-primary" />
                        Northeast now
                      </p>
                      <div className="grid gap-1">
                        {DISCOVERY_COPY.suggestions.map((item) => (
                          <button
                            key={item}
                            onClick={() => {
                              setSearchQuery(item)
                              setIsSearchFocused(false)
                            }}
                            className="flex items-center gap-3 rounded-xl px-3 py-2.5 text-left text-sm text-foreground/90 transition-colors hover:bg-white/5"
                          >
                            <div className="flex h-6 w-6 items-center justify-center rounded-full bg-white/5">
                              <MapPin className="h-3 w-3 text-muted-foreground" />
                            </div>
                            {item}
                          </button>
                        ))}
                      </div>
                    </div>
                    <div>
                      <p className="mb-3 text-[10px] uppercase tracking-widest text-muted-foreground/60">
                        Discover by mood
                      </p>
                      <div className="flex flex-wrap gap-2">
                        {NORTHEAST_MOODS.slice(0, 6).map((mood) => (
                          <button
                            key={mood.tag}
                            onClick={() => {
                              setSelectedMood(mood.tag)
                              setIsSearchFocused(false)
                            }}
                            className="rounded-full border border-white/5 bg-white/5 px-3 py-1.5 text-xs text-muted-foreground transition-colors hover:bg-white/10 hover:text-foreground"
                          >
                            {mood.label}
                          </button>
                        ))}
                      </div>
                    </div>
                  </div>
                ) : (
                  <div className="py-4 text-center text-sm font-serif italic text-muted-foreground">
  // eslint-disable-next-line react/no-unescaped-entities
                    Press search to explore Northeast results for "{searchQuery}"
                  </div>
                )}
              </motion.div>
            )}
          </AnimatePresence>
        </div>

        <div className="grid grid-cols-1 gap-0 border-b border-white/5 md:grid-cols-2">
          <div className="border-b border-white/5 p-4 md:border-b-0 md:border-r md:border-white/5">
            <span className="mb-2 block text-[10px] font-medium uppercase tracking-widest text-muted-foreground/60">
              Destination
            </span>
            <select
              value={selectedDestination}
              onChange={(event) => setSelectedDestination(event.target.value)}
              className="w-full bg-transparent text-sm text-foreground outline-none"
            >
              <option value="">Anywhere in the Northeast</option>
              {NORTHEAST_DESTINATIONS.map((destination) => (
                <option key={destination} value={destination} className="bg-[#141414]">
                  {destination}
                </option>
              ))}
            </select>
          </div>
          <div className="p-4">
            <span className="mb-2 block text-[10px] font-medium uppercase tracking-widest text-muted-foreground/60">
              Mood
            </span>
            <select
              value={selectedMood}
              onChange={(event) => setSelectedMood(event.target.value)}
              className="w-full bg-transparent text-sm text-foreground outline-none"
            >
              <option value="">Choose a travel rhythm</option>
              {NORTHEAST_MOODS.map((mood) => (
                <option key={mood.tag} value={mood.tag} className="bg-[#141414]">
                  {mood.label}
                </option>
              ))}
            </select>
          </div>
        </div>

        <div className="flex items-center">
          <Popover open={isCalendarOpen} onOpenChange={setIsCalendarOpen}>
            <PopoverTrigger asChild>
              <button className="flex flex-1 items-center gap-3 rounded-bl-[2rem] border-r border-white/5 p-4 text-left transition-colors hover:bg-white/[0.02]">
                <CalendarIcon className={`h-4 w-4 ${date ? "text-primary" : "text-muted-foreground"}`} />
                <div className="flex flex-col">
                  <span className="text-[10px] font-medium uppercase tracking-widest text-muted-foreground/60">
                    When
                  </span>
                  <span className={`text-sm ${date ? "text-foreground" : "text-muted-foreground"}`}>
                    {date?.from ? (
                      date.to ? (
                        <>
                          {format(date.from, "LLL dd")} - {format(date.to, "LLL dd")}
                        </>
                      ) : (
                        format(date.from, "LLL dd")
                      )
                    ) : (
                      "Add dates"
                    )}
                  </span>
                </div>
              </button>
            </PopoverTrigger>
            <PopoverContent className="w-auto border-white/10 bg-[#141414] p-0" align="start">
              <Calendar
                initialFocus
                mode="range"
                defaultMonth={date?.from}
                selected={date}
                onSelect={setDate}
                numberOfMonths={2}
                className="rounded-xl"
              />
            </PopoverContent>
          </Popover>

          <Popover open={isTravelerOpen} onOpenChange={setIsTravelerOpen}>
            <PopoverTrigger asChild>
              <button className="flex flex-1 items-center gap-3 p-4 text-left transition-colors hover:bg-white/[0.02]">
                <Users className={`h-4 w-4 ${travelers > 1 ? "text-primary" : "text-muted-foreground"}`} />
                <div className="flex flex-col">
                  <span className="text-[10px] font-medium uppercase tracking-widest text-muted-foreground/60">
                    Who
                  </span>
                  <span className="text-sm text-foreground">
                    {travelers} {travelers === 1 ? "Traveler" : "Travelers"}
                  </span>
                </div>
              </button>
            </PopoverTrigger>
            <PopoverContent className="w-64 rounded-2xl border-white/10 bg-[#141414] p-4" align="start">
              <div className="flex items-center justify-between">
                <div>
                  <p className="text-sm font-medium text-foreground">Travelers</p>
                  <p className="text-xs text-muted-foreground">Adults and shared room plans</p>
                </div>
                <div className="flex items-center gap-3">
                  <button
                    onClick={() => setTravelers(Math.max(1, travelers - 1))}
                    disabled={travelers <= 1}
                    className="flex h-8 w-8 items-center justify-center rounded-full border border-white/10 text-foreground transition-colors hover:bg-white/5 disabled:opacity-50"
                  >
                    -
                  </button>
                  <span className="w-4 text-center text-sm font-medium">{travelers}</span>
                  <button
                    onClick={() => setTravelers(Math.min(20, travelers + 1))}
                    className="flex h-8 w-8 items-center justify-center rounded-full border border-white/10 text-foreground transition-colors hover:bg-white/5"
                  >
                    +
                  </button>
                </div>
              </div>
            </PopoverContent>
          </Popover>
        </div>
      </motion.div>

      <div className="flex flex-wrap gap-2">
        {NORTHEAST_MOODS.slice(0, 4).map((mood) => {
          const isActive = selectedMood === mood.tag
          return (
            <button
              key={mood.tag}
              onClick={() => setSelectedMood(isActive ? "" : mood.tag)}
              className={`rounded-full border px-3 py-1.5 text-xs transition-colors ${
                isActive
                  ? "border-primary/30 bg-primary/10 text-primary"
                  : "border-white/5 bg-white/5 text-muted-foreground hover:bg-white/10 hover:text-foreground"
              }`}
            >
              {mood.label}
            </button>
          )
        })}
        {activeMood && (
          <div className="rounded-full border border-white/10 bg-white/5 px-3 py-1.5 text-xs text-muted-foreground">
            {activeMood.description}
          </div>
        )}
      </div>

      <motion.button
        whileHover={{ scale: 1.01 }}
        whileTap={{ scale: 0.98 }}
        onClick={handleSearch}
        className="mt-2 flex h-14 w-full items-center justify-center gap-2 rounded-full bg-primary text-base font-medium tracking-wide text-primary-foreground shadow-[0_8px_30px_rgba(var(--primary-rgb),0.3)] transition-shadow hover:shadow-[0_8px_40px_rgba(var(--primary-rgb),0.4)]"
      >
        {productType === "stays"
          ? "Find Northeast stays"
          : productType === "trips"
            ? "Find Northeast trips"
            : "Start Northeast discovery"}
        <Navigation className="h-4 w-4" />
      </motion.button>
    </div>
  )
}

