                  <Link
                    href={`/booking/stay/${stay.id}?room=${encodeURIComponent(stay.roomTypes[selectedRoom]?.name)}`}
                    className="relative group inline-flex"
                  >
                    <div className="absolute -inset-1 bg-gradient-to-r from-primary/50 to-primary/20 rounded-full blur opacity-20 group-hover:opacity-60 transition duration-1000 group-hover:duration-200" />
                    <div className="relative px-16 py-6 bg-primary text-black rounded-full font-sans text-xs uppercase tracking-[0.4em] font-bold flex items-center gap-4 hover:shadow-[0_0_30px_rgba(230,184,115,0.4)] transition-all duration-500">
                      Reserve Quarters
                      <ArrowDown className="h-4 w-4 -rotate-90 group-hover:translate-x-1 transition-transform" />
                    </div>
                  </Link>
                </Magnetic>

                <Link 
                  href={`https://wa.me/917629877144?text=${encodeURIComponent(`Hi! I'm looking at ${stay.name} (${stay.roomTypes[selectedRoom]?.name}). Can you help me with a booking?`)}`}
                  target="_blank"
                  className="mt-8 text-[10px] uppercase tracking-[0.4em] text-muted-foreground dark:text-white/20 hover:text-primary transition-colors font-bold"
                >
                  Chat with Concierge
                </Link>
              </div>

            </div>
          </motion.div>
        </div>
      </section>

      <Footer />

      {/* ── STICKY MOBILE CTA ──────────────────────────────── */}
      <div className="fixed bottom-0 left-0 right-0 p-4 md:hidden z-40 bg-background/90 backdrop-blur-md border-t border-border pb-[calc(env(safe-area-inset-bottom)+1rem)]">
        <Link 
          href={`/booking/stay/${stay.id}?room=${encodeURIComponent(stay.roomTypes[selectedRoom]?.name)}`}
          className="w-full flex items-center justify-center py-4 bg-primary text-black rounded-xl font-sans text-xs uppercase tracking-[0.4em] font-bold"
        >
          Check Dates & Book
        </Link>
      </div>

      {/* ── WHATSAPP HELP TOAST ────────────────────────────── */}
      <WhatsAppHelpToast 
        isVisible={showWhatsAppPrompt}
        onDismiss={() => setShowWhatsAppPrompt(false)}
        propertyName={stay.name}
      />
    </main>
  )
}
